CREATE TABLE feed_groups(owner_id text NOT NULL REFERENCES users(id),id text NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 40),mode text NOT NULL DEFAULT 'news' CHECK(mode IN ('news','people')),people jsonb NOT NULL DEFAULT '["trump","duan"]',subscriptions jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,id));
CREATE TABLE feed_preferences(owner_id text PRIMARY KEY REFERENCES users(id),instructions text NOT NULL DEFAULT '',revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),enabled boolean NOT NULL DEFAULT false,interval_minutes integer NOT NULL DEFAULT 360,updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE feed_group_preferences(owner_id text NOT NULL,group_id text NOT NULL,instructions text NOT NULL DEFAULT '',revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),enabled boolean NOT NULL DEFAULT false,interval_minutes integer NOT NULL DEFAULT 360,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,group_id),FOREIGN KEY(owner_id,group_id) REFERENCES feed_groups(owner_id,id));
CREATE TABLE feed_agent_profiles(owner_id text PRIMARY KEY REFERENCES users(id),name text NOT NULL DEFAULT 'Alcor',image text,revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE feed_posts(owner_id text NOT NULL,id text NOT NULL,group_id text NOT NULL,fingerprint text NOT NULL,payload jsonb NOT NULL,kind text NOT NULL CHECK(kind IN ('news','people')),author_key text,source_revision text NOT NULL,source_page_id text NOT NULL,sort_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,group_id,fingerprint),FOREIGN KEY(owner_id,group_id) REFERENCES feed_groups(owner_id,id));
CREATE INDEX feed_posts_page ON feed_posts(owner_id,group_id,sort_at DESC,id DESC);
CREATE TRIGGER immutable_feed_post BEFORE UPDATE OR DELETE ON feed_posts FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
CREATE TABLE feed_post_marks(owner_id text NOT NULL,post_id text NOT NULL,liked boolean NOT NULL DEFAULT false,hidden boolean NOT NULL DEFAULT false,revision bigint NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,post_id),FOREIGN KEY(owner_id,post_id) REFERENCES feed_posts(owner_id,id));
CREATE TABLE feed_messages(owner_id text NOT NULL,id text NOT NULL,post_id text NOT NULL,request_id uuid NOT NULL,role text NOT NULL CHECK(role IN ('user','assistant')),text text NOT NULL,source_revision text,source_page_id text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,id),UNIQUE(owner_id,request_id,role),FOREIGN KEY(owner_id,post_id) REFERENCES feed_posts(owner_id,id),CHECK(role='user' OR (source_revision IS NOT NULL AND source_page_id IS NOT NULL)));
CREATE TRIGGER immutable_feed_message BEFORE UPDATE OR DELETE ON feed_messages FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
CREATE TABLE feed_operations(owner_id text NOT NULL REFERENCES users(id),request_id uuid NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(owner_id,request_id));
CREATE TRIGGER immutable_feed_operation BEFORE UPDATE OR DELETE ON feed_operations FOR EACH ROW EXECUTE FUNCTION immutable_trade_ledger();
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['feed_groups','feed_group_preferences','feed_agent_profiles','feed_preferences','feed_posts','feed_post_marks','feed_messages'] LOOP
INSERT INTO account_change_sources(domain,source_table,owner_column,selected_columns,ignored_columns) VALUES('feed',tab,'owner_id','','') ON CONFLICT(domain,source_table) DO NOTHING;
EXECUTE format('CREATE TRIGGER account_signal_feed AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION capture_account_change(''feed'',''owner_id'','''','''')',tab);
END LOOP; END $$;
